import threading

class CounterJob:
    def __init__(self):
        self.count = 0

    def increment(self, times: int) -> None:
        for _ in range(times):
            current = self.count
            self.count = current + 1

    def run(self, workers: int = 2, per_worker: int = 100_000) -> int:
        threads = [
            threading.Thread(target=self.increment, args=(per_worker,))
            for _ in range(workers)
        ]
        for t in threads:
            t.start()
        for t in threads:
            t.join()
        return self.count
```

